cat > deepseek.js << 'CEOF'
const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');
const readline = require('readline');

const CHROMIUM_PATH = '/data/data/com.termux/files/usr/bin/chromium-browser';
const DEEPSEEK_BASE = 'https://chat.deepseek.com/';

const HISTORY_FILE = path.join(__dirname, 'chat-history.json');
const CACHE_DIR = path.join(__dirname, '.cache');
const ENDPOINT_CACHE_FILE = path.join(CACHE_DIR, 'endpoint-cache.json');

const wait = ms => new Promise(r => setTimeout(r, ms));

let browser;
let page;
let chatLog = {};
let systemPrompt = null;

const endpointCache = {
  selectors: {},
  endpoints: {},
  lastUpdated: null
};

function ensureCacheDir() {
  if (!fs.existsSync(CACHE_DIR)) {
    fs.mkdirSync(CACHE_DIR, { recursive: true });
  }
}

function loadEndpointCache() {
  ensureCacheDir();

  if (fs.existsSync(ENDPOINT_CACHE_FILE)) {
    try {
      const parsed = JSON.parse(fs.readFileSync(ENDPOINT_CACHE_FILE, 'utf8'));
      Object.assign(endpointCache, parsed);
    } catch {}
  }
}

function saveEndpointCache() {
  endpointCache.lastUpdated = Date.now();
  fs.writeFileSync(
    ENDPOINT_CACHE_FILE,
    JSON.stringify(endpointCache, null, 2)
  );
}

function loadChatHistory() {
  if (fs.existsSync(HISTORY_FILE)) {
    try {
      chatLog = JSON.parse(fs.readFileSync(HISTORY_FILE, 'utf8'));
    } catch {
      chatLog = {};
    }
  }
}

function saveChatHistory() {
  fs.writeFileSync(
    HISTORY_FILE,
    JSON.stringify(chatLog, null, 2)
  );
}

async function typeIntoReactInput(el, text) {
  await el.evaluate((node, value) => {
    const setter = Object.getOwnPropertyDescriptor(
      window.HTMLTextAreaElement.prototype,
      'value'
    ).set;

    setter.call(node, value);

    node.dispatchEvent(new Event('input', { bubbles: true }));
    node.dispatchEvent(new Event('change', { bubbles: true }));
  }, text);
}

async function resetReplyState() {
  await page.evaluate(() => {
    window.__deepseekReplyReady = false;
    window.__deepseekAssistantReply = '';
    window.__deepseekStreamChunks = [];
    window.__deepseekLastRequest = null;
    window.__deepseekLastResponse = null;
  });
}

async function installFetchHooks() {
  await page.evaluate((sp) => {
    if (window.__deepseekHooksInstalled) return;

    window.__deepseekHooksInstalled = true;
    window.__deepseekSystemPrompt = sp;

    const origFetch = window.fetch;

    window.fetch = async function(...args) {
      const [url, options] = args;

      try {
        if (typeof url === 'string') {

          if (
            url.includes('/chat/completion') ||
            url.includes('/api/v0/chat/completion')
          ) {

            if (options?.body) {
              try {
                const body = JSON.parse(options.body);

                if (window.__deepseekSystemPrompt) {

                  if (Array.isArray(body.messages)) {

                    const already = body.messages.some(
                      m => m && m.role === 'system'
                    );

                    if (!already) {
                      body.messages.unshift({
                        role: 'system',
                        content: window.__deepseekSystemPrompt
                      });
                    }

                  } else if (typeof body.prompt === 'string') {

                    body.prompt =
                      window.__deepseekSystemPrompt +
                      '\n\n' +
                      body.prompt;
                  }
                }

                options.body = JSON.stringify(body);

                window.__deepseekLastRequest = {
                  url,
                  body
                };

              } catch {}
            }

            const response = await origFetch(url, options);

            response.clone().text().then(text => {

              window.__deepseekLastResponse = text;

              let assistant = '';

              for (const line of text.split('\n')) {

                if (!line.startsWith('data:')) continue;

                try {
                  const parsed = JSON.parse(
                    line.slice(5).trim()
                  );

                  if (parsed.o === 'replace' && parsed.v) {
                    assistant = parsed.v;
                  }

                  else if (parsed.o === 'append' && parsed.v) {
                    assistant += parsed.v;
                  }

                  window.__deepseekStreamChunks.push(parsed);

                } catch {}
              }

              if (assistant) {
                window.__deepseekAssistantReply = assistant;
                window.__deepseekReplyReady = true;
              }

            }).catch(() => {});

            return response;
          }

        }

      } catch {}

      return origFetch(...args);
    };

  }, systemPrompt);
}

async function discoverRuntime() {

  console.log('🔎 Discovering runtime selectors/endpoints...');

  const discovery = await page.evaluate(() => {

    const q = sel => document.querySelector(sel);

    const textarea =
      q('textarea') ||
      q('textarea[placeholder*="DeepSeek"]');

    const sendButton =
      [...document.querySelectorAll('button')]
      .find(btn => {
        const rect = btn.getBoundingClientRect();
        return rect.width > 20 &&
               rect.height > 20 &&
               !btn.disabled;
      });

    const fileInputs = [
      ...document.querySelectorAll('input[type="file"]')
    ].map(el => ({
      accept: el.accept,
      hidden: el.hidden,
      disabled: el.disabled
    }));

    const radios = [
      ...document.querySelectorAll('[role="radio"]')
    ].map(el => ({
      text: el.innerText,
      checked: el.getAttribute('aria-checked'),
      model: el.dataset?.modelType || null
    }));

    return {
      textareaExists: !!textarea,
      sendButtonExists: !!sendButton,
      fileInputs,
      radios
    };
  });

  endpointCache.discovery = discovery;
  saveEndpointCache();

  console.log(JSON.stringify(discovery, null, 2));
}

async function waitForUploadCompletion(timeout = 30000) {

  return new Promise(resolve => {

    const started = Date.now();

    const listener = async resp => {

      const url = resp.url();

      if (
        url.includes('/upload') ||
        url.includes('/file')
      ) {

        try {

          const body = await resp.text();

          page.off('response', listener);

          resolve({
            ok: true,
            status: resp.status(),
            url,
            body
          });

        } catch {

          page.off('response', listener);

          resolve({
            ok: false,
            status: resp.status(),
            url
          });
        }
      }
    };

    page.on('response', listener);

    const timer = setInterval(() => {

      if (Date.now() - started > timeout) {

        clearInterval(timer);
        page.off('response', listener);

        resolve({
          ok: false,
          timeout: true
        });
      }

    }, 250);
  });
}

async function uploadFile(filePath) {

  const absPath = path.resolve(filePath);

  if (!fs.existsSync(absPath)) {
    console.log(`❌ Missing file: ${absPath}`);
    return false;
  }

  const fileInputs = await page.$$('input[type="file"]');

  if (fileInputs.length > 0) {

    console.log('📎 Using direct file input upload...');

    const uploadPromise = waitForUploadCompletion();

    await fileInputs[0].uploadFile(absPath);

    const result = await uploadPromise;

    if (result.ok) {

      console.log('✅ Upload complete.');
      console.log(`🌐 ${result.url}`);

      return true;
    }

    console.log('⚠️ Upload API not detected.');
    return false;
  }

  console.log('⚠️ No direct file input found.');

  const paperclipCandidates = await page.$$('*');

  for (const el of paperclipCandidates) {

    try {

      const cls = await el.evaluate(
        n => n.className || ''
      );

      if (
        typeof cls === 'string' &&
        (
          cls.includes('f02f0e25') ||
          cls.toLowerCase().includes('upload')
        )
      ) {

        console.log('📎 Found upload trigger.');

        const uploadPromise = waitForUploadCompletion();

        const [chooser] = await Promise.all([
          page.waitForFileChooser({
            timeout: 10000
          }),
          el.click()
        ]);

        await chooser.accept([absPath]);

        const result = await uploadPromise;

        if (result.ok) {
          console.log('✅ Upload complete.');
          return true;
        }

        console.log('⚠️ Upload request never completed.');
        return false;
      }

    } catch {}
  }

  console.log('❌ Upload mechanism unavailable.');
  return false;
}

async function waitForReply(timeout = 120000) {

  try {

    await page.waitForFunction(
      () => window.__deepseekReplyReady === true,
      { timeout }
    );

    return await page.evaluate(
      () => window.__deepseekAssistantReply || ''
    );

  } catch {

    console.log('⚠️ SSE wait timed out. Falling back to DOM scrape...');

    try {

      const domReply = await page.evaluate(() => {

        const msgs = [
          ...document.querySelectorAll(
            '.ds-markdown, .markdown, .message-content'
          )
        ];

        if (!msgs.length) return '';

        return msgs[msgs.length - 1].innerText || '';
      });

      return domReply;

    } catch {
      return '';
    }
  }
}

async function handleAutoRetry() {

  const reply = await page.evaluate(
    () => window.__deepseekAssistantReply || ''
  );

  if (
    /server is busy/i.test(reply) ||
    /thought for 0 seconds/i.test(reply)
  ) {

    console.log('⚠️ Auto retry triggered.');

    const retryButton = await page.$(
      'div.ds-icon-button'
    );

    if (retryButton) {

      await resetReplyState();

      await retryButton.click();

      return await waitForReply();
    }
  }

  return reply;
}

async function sendMessage(
  prompt,
  edit = false,
  attachFile = null
) {

  await resetReplyState();

  if (attachFile) {

    const uploaded = await uploadFile(attachFile);

    if (!uploaded) {
      console.log('⚠️ Continuing without attachment.');
    }

    await wait(1000);
  }

  const textarea =
    await page.$('textarea') ||
    await page.$(
      'textarea[placeholder*="DeepSeek"]'
    );

  if (!textarea) {
    throw new Error('Textarea not found.');
  }

  await textarea.click();

  await typeIntoReactInput(
    textarea,
    prompt
  );

  await wait(250);

  const buttons = await page.$$('button');

  let sendButton = null;

  for (const btn of buttons) {

    try {

      const enabled = await btn.evaluate(el =>
        !el.disabled &&
        el.getAttribute('aria-disabled') !== 'true'
      );

      if (!enabled) continue;

      const box = await btn.boundingBox();

      if (
        box &&
        box.width > 20 &&
        box.height > 20
      ) {
        sendButton = btn;
      }

    } catch {}
  }

  if (!sendButton) {
    throw new Error('Send button not found.');
  }

  await sendButton.click();

  console.log('📤 Message sent.');

  const reply = await waitForReply();

  return await handleAutoRetry() || reply;
}

async function initSession(sessionId = null) {

  browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROMIUM_PATH,
    userDataDir: './browser-data',
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu'
    ]
  });

  page = await browser.newPage();

  page.on('request', req => {

    const url = req.url();

    if (
      url.includes('/api/') ||
      url.includes('/chat/')
    ) {

      endpointCache.endpoints[url] = {
        method: req.method(),
        ts: Date.now()
      };
    }
  });

  const target =
    sessionId
      ? `${DEEPSEEK_BASE}a/chat/s/${sessionId}`
      : DEEPSEEK_BASE;

  await page.goto(target, {
    waitUntil: 'networkidle2',
    timeout: 30000
  });

  await wait(2500);

  if (page.url().includes('/sign_in')) {

    console.error('❌ Authentication required.');

    await browser.close();
    process.exit(1);
  }

  console.log('✅ Authenticated.');

  const expert = await page.$(
    'div[data-model-type="expert"][role="radio"]'
  );

  if (expert) {

    const checked = await page.evaluate(
      el => el.getAttribute('aria-checked'),
      expert
    );

    if (checked !== 'true') {

      console.log('🧠 Enabling Expert mode...');

      await expert.click();

      await wait(1000);
    }
  }

  await installFetchHooks();

  await discoverRuntime();
}

async function main() {

  loadChatHistory();
  loadEndpointCache();

  const args = process.argv.slice(2);

  let sessionId = null;
  let attachFile = null;
  let loopMode = false;
  let listMode = false;
  let editMode = false;
  let showLog = false;

  let prompt = '';

  let promptIndex = args.findIndex(
    a => !a.startsWith('--')
  );

  if (promptIndex > -1) {

    prompt = args
      .slice(promptIndex)
      .join(' ');

    args.splice(promptIndex);
  }

  for (let i = 0; i < args.length; i++) {

    if (
      args[i] === '--session' &&
      args[i + 1]
    ) {
      sessionId = args[++i];
    }

    else if (
      args[i] === '--attach' &&
      args[i + 1]
    ) {
      attachFile = args[++i];
    }

    else if (
      args[i] === '--system-prompt' &&
      args[i + 1]
    ) {
      systemPrompt = args[++i];
    }

    else if (args[i] === '--loop') {
      loopMode = true;
    }

    else if (args[i] === '--list') {
      listMode = true;
    }

    else if (args[i] === '--edit') {
      editMode = true;
    }

    else if (args[i] === '--log') {
      showLog = true;
    }
  }

  if (showLog) {
    console.log(
      JSON.stringify(chatLog, null, 2)
    );
    return;
  }

  await initSession(sessionId);

  if (listMode) {

    console.log('📋 Sessions:\n');

    Object.keys(chatLog).forEach(id => {
      console.log(
        `${id} :: ${chatLog[id].title || 'Untitled'}`
      );
    });

    await browser.close();
    return;
  }

  if (loopMode) {

    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    for await (const line of rl) {

      const trimmed = line.trim();

      if (!trimmed) continue;

      const reply = await sendMessage(
        trimmed,
        editMode,
        attachFile
      );

      console.log('\n');
      console.log(reply);
      console.log('\n');

      attachFile = null;
      editMode = false;
    }

    await browser.close();
    return;
  }

  if (!prompt) {

    console.log(`
Usage:

node deepseek.js "prompt"

node deepseek.js --attach file.txt "prompt"

node deepseek.js --loop

node deepseek.js --session ID "prompt"
`);

    process.exit(1);
  }

  const reply = await sendMessage(
    prompt,
    editMode,
    attachFile
  );

  console.log('\n');
  console.log(reply);
  console.log('\n');

  const currentUrl = new URL(page.url());

  const currentId =
    sessionId ||
    currentUrl.pathname.split('/').pop() ||
    'unknown';

  if (!chatLog[currentId]) {

    chatLog[currentId] = {
      title: await page.title(),
      messages: []
    };
  }

  chatLog[currentId].messages.push({
    role: 'user',
    content: prompt,
    time: Date.now()
  });

  chatLog[currentId].messages.push({
    role: 'assistant',
    content: reply,
    time: Date.now()
  });

  saveChatHistory();
  saveEndpointCache();

  console.log(`🔗 Session ID: ${currentId}`);

  await browser.close();
}

main().catch(async err => {

  console.error(
    '💥 Fatal error:',
    err.message
  );

  try {
    if (browser) await browser.close();
  } catch {}

  process.exit(2);
});
