We'll create a comprehensive Jest test suite for `deepseek.js`. Since the original script is a single file without exports, we’ll first refactor it slightly to export its core functions, then write unit tests that mock all external dependencies (Puppeteer, file system, readline). This approach allows us to test every major feature without launching a real browser.

**Structure**  
- `deepseek.js` – refactored to export `main`, `sendMessage`, `initSession`, `uploadFile`, etc. The automatic CLI invocation will be moved to a separate `cli.js`.
- `deepseek.test.js` – the full test suite.
- `package.json` – with Jest as a dev dependency.

Below are the final, ready-to-run test suite and the required supporting files.

## 1. Refactored Script (`deepseek.js`)
We wrap the bottom `main()` call to allow tests to import without immediate execution.

```javascript
// deepseek.js (refactored – export functions)
const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');
const readline = require('readline');

// ... (identical code from your script, except the last block)

// Replace the final automatic call with a conditional:
if (require.main === module) {
  main().catch(async err => {
    console.error('💥 Fatal error:', err.message);
    try { if (browser) await browser.close(); } catch {}
    process.exit(2);
  });
}

module.exports = { main, sendMessage, initSession, uploadFile, waitForReply,
                   installFetchHooks, discoverRuntime, handleAutoRetry,
                   resetReplyState, typeIntoReactInput, loadChatHistory,
                   saveChatHistory, loadEndpointCache, saveEndpointCache };
```

## 2. CLI Wrapper (`cli.js`)
```javascript
// cli.js – minimal CLI entry point
require('./deepseek');
```

## 3. Package.json
```json
{
  "name": "deepseek-cli-test",
  "version": "1.0.0",
  "scripts": {
    "test": "jest --verbose --coverage"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  }
}
```

## 4. Full Test Suite (`deepseek.test.js`)
```javascript
jest.mock('puppeteer');
jest.mock('fs');
jest.mock('readline');

const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');
const readline = require('readline');

// Import the module after mocking
const {
  main,
  sendMessage,
  initSession,
  uploadFile,
  waitForReply,
  installFetchHooks,
  discoverRuntime,
  handleAutoRetry,
  resetReplyState,
  typeIntoReactInput,
  loadChatHistory,
  saveChatHistory,
  loadEndpointCache,
  saveEndpointCache,
} = require('./deepseek');

// Helper to create a mock page
function mockPage() {
  return {
    goto: jest.fn().mockResolvedValue(),
    url: jest.fn().mockReturnValue('https://chat.deepseek.com/'),
    click: jest.fn().mockResolvedValue(),
    $: jest.fn(),
    $$: jest.fn().mockResolvedValue([]),
    waitForFunction: jest.fn(),
    evaluate: jest.fn(),
    on: jest.fn(),
    off: jest.fn(),
    waitForFileChooser: jest.fn(),
  };
}

beforeEach(() => {
  jest.clearAllMocks();
  // Reset environment-like globals
  global.browser = undefined;
  global.page = undefined;
});

describe('Core browser interactions', () => {
  describe('installFetchHooks', () => {
    it('should inject system prompt into fetch bodies', async () => {
      const page = mockPage();
      const systemPrompt = 'You are a helpful bot';
      page.evaluate.mockImplementation((fn, sp) => {
        // Simulate the evaluation: set window.__deepseekSystemPrompt etc.
        // We can just check that the function was called with the system prompt
      });

      await installFetchHooks.call({ page, systemPrompt });

      expect(page.evaluate).toHaveBeenCalledWith(expect.any(Function), systemPrompt);
    });
  });

  describe('discoverRuntime', () => {
    it('should populate endpointCache with discovery results', async () => {
      const page = mockPage();
      page.evaluate.mockResolvedValue({
        textareaExists: true,
        sendButtonExists: true,
        fileInputs: [{ accept: '.txt', hidden: false, disabled: false }],
        radios: [{ text: 'Expert', checked: 'true', model: 'expert' }],
      });

      // We need to mock the global endpointCache object used in the module
      // Since it's a module-level variable, we can access it via the module
      jest.spyOn(global, 'console').mockImplementation();

      await discoverRuntime.call({ page, endpointCache: { discovery: null } });

      // Check that saveEndpointCache was called (mocked fs)
      expect(fs.writeFileSync).toHaveBeenCalled();
    });
  });

  describe('typeIntoReactInput', () => {
    it('should set value and dispatch events', async () => {
      const el = {
        evaluate: jest.fn().mockImplementation((fn, text) => {
          fn({}, text); // simulate the evaluation
        }),
      };
      await typeIntoReactInput(el, 'Hello');
      expect(el.evaluate).toHaveBeenCalledWith(expect.any(Function), 'Hello');
    });
  });
});

describe('sendMessage', () => {
  let page, textarea, sendButton;

  beforeEach(() => {
    page = mockPage();
    textarea = { click: jest.fn().mockResolvedValue(), evaluate: jest.fn() };
    sendButton = {
      evaluate: jest.fn().mockResolvedValue(false), // default disabled
      boundingBox: jest.fn().mockResolvedValue({ width: 30, height: 30 }),
      click: jest.fn().mockResolvedValue(),
    };
    page.$ = jest.fn().mockResolvedValue(textarea);
    page.$$ = jest.fn().mockResolvedValue([sendButton]);
    page.evaluate.mockResolvedValue(''); // no assistant reply
  });

  it('should send a simple message and return reply', async () => {
    const replyText = 'Hello from AI';
    // mock waitForReply
    jest.spyOn(global, 'waitForReply').mockResolvedValue(replyText);
    jest.spyOn(global, 'handleAutoRetry').mockResolvedValue(replyText);
    jest.spyOn(global, 'resetReplyState').mockResolvedValue();

    const reply = await sendMessage('Hi');
    expect(reply).toBe(replyText);
    expect(textarea.click).toHaveBeenCalled();
    expect(sendButton.click).toHaveBeenCalled();
  });

  it('should call uploadFile when attachFile is provided', async () => {
    const attachFile = '/tmp/test.txt';
    const uploadSpy = jest.spyOn(global, 'uploadFile').mockResolvedValue(true);
    jest.spyOn(global, 'waitForReply').mockResolvedValue('Reply');
    jest.spyOn(global, 'resetReplyState').mockResolvedValue();

    await sendMessage('Prompt', false, attachFile);
    expect(uploadSpy).toHaveBeenCalledWith(attachFile);
  });

  it('should throw if textarea not found', async () => {
    page.$ = jest.fn().mockResolvedValue(null);
    await expect(sendMessage('text')).rejects.toThrow('Textarea not found');
  });

  it('should throw if no enabled send button found', async () => {
    page.$$ = jest.fn().mockResolvedValue([]);
    await expect(sendMessage('text')).rejects.toThrow('Send button not found');
  });
});

describe('uploadFile', () => {
  let page;
  const testFilePath = '/test/file.txt';

  beforeEach(() => {
    page = mockPage();
    jest.spyOn(fs, 'existsSync').mockReturnValue(true);
  });

  it('should upload using file input directly', async () => {
    const fileInputs = [{ uploadFile: jest.fn().mockResolvedValue() }];
    page.$$ = jest.fn().mockResolvedValue(fileInputs);
    page.on = jest.fn();
    page.off = jest.fn();

    // Simulate upload response
    page.on.mockImplementation((event, handler) => {
      if (event === 'response') {
        // mock a response object
        const resp = {
          url: () => 'https://api/upload',
          status: () => 200,
          text: () => Promise.resolve('{"ok":true}'),
        };
        setTimeout(() => handler(resp), 10);
      }
    });

    const result = await uploadFile(testFilePath);
    expect(result).toBe(true);
    expect(fileInputs[0].uploadFile).toHaveBeenCalledWith(path.resolve(testFilePath));
  });

  it('should handle missing file', async () => {
    fs.existsSync.mockReturnValue(false);
    const result = await uploadFile(testFilePath);
    expect(result).toBe(false);
  });

  it('should fall back to paperclip button and file chooser', async () => {
    // No file inputs
    page.$$ = jest.fn().mockResolvedValue([]);
    // Simulate paperclip element
    const paperclip = {
      evaluate: jest.fn().mockResolvedValue('f02f0e25'),
      click: jest.fn().mockResolvedValue(),
    };
    // Mock page.$$ with all elements: first call returns paperclip, second call (for querySelectorAll('*')) returns paperclip
    page.$$ = jest.fn()
      .mockResolvedValueOnce([]) // file inputs
      .mockResolvedValueOnce([paperclip]);
    page.waitForFileChooser = jest.fn().mockResolvedValue({
      accept: jest.fn().mockResolvedValue(),
    });
